      }
    ],
    "medical_safety_risk_recognition": [
      {
        "event_id": "lite_evt_00083",
        "explanation": "The doctor recognized important emergency triggers but did not include the full required red-flag set.",
        "quote": "咯血、胸痛气喘明显、高烧寒战或者晕过去"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
